<?php
require_once '../includes/auth.php';requireLogin();requireTenantContext();$tenantId=getCurrentTenantId();$rows=[];$q=$conn->query("SHOW TABLES LIKE 'hotspot_access_codes'");if($q&&$q->num_rows){$sql="SELECT * FROM hotspot_access_codes";if($tenantId)$sql.=" WHERE tenant_id=".(int)$tenantId;$sql.=" ORDER BY id DESC LIMIT 200";$r=$conn->query($sql);if($r)while($x=$r->fetch_assoc())$rows[]=$x;}
$pageTitle='Hotspot Access Codes';require_once '../includes/header.php';?><div class="dashboard-card"><h2>Access Codes</h2><?php if(!$rows):?><p>No access codes found.</p><?php else:?><div class="table-responsive"><table><thead><tr><?php foreach(array_keys($rows[0]) as $k):?><th><?=e(ucwords(str_replace('_',' ',$k)))?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $x):?><tr><?php foreach($x as $v):?><td><?=e($v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php require_once '../includes/footer.php';?>